/**
 * Background / outline extracted from `dgm:bg` and `dgm:whole`.
 *
 * @example
 * ```ts
 * const chrome: PptxSmartArtChrome = {
 *   backgroundColor: "#F0F0F0",
 *   outlineColor: "#333333",
 *   outlineWidth: 1,
 * };
 * // => satisfies PptxSmartArtChrome
 * ```
 */
