  isParagraphBreak?: boolean;
  /** This entry is a soft line break (`a:br`) rather than carrying text. */
  isLineBreak?: boolean;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strikethrough?: boolean;
