  /** OOXML `a:prstDash@val` (e.g. `solid`, `dash`, `sysDot`). */
  dash?: string;
  /** Border colour as a theme scheme fill (from `a:ln/a:solidFill/a:schemeClr`). */
  fill?: ParsedTableStyleFill;
  /** Explicit hex colour when the line used `a:srgbClr` (e.g. `#808080`). */
