  /** Master switch. Default true. */
  enabled?: boolean;
  /** How long the motion + glow plays, in ms. Default 900. */
  durationMs?: number;
  /** Draw the pulsing glow highlight on changed elements. Default true. */
  glow?: boolean;
  /** Glide old->new bounds and cross-fade colours. Default true. */
